INSERT IGNORE INTO `tieu_chi` (`tc_id`, `name_tc`, `nhom_tc_id`, `description`, `min_score`, `max_score`) VALUES
(1, 'Luận Điểm và Mức Độ Hiểu', 1, '- Luận điểm chính (thesis) rõ ràng, sắc sảo, có tính khám phá.\r\n- Thể hiện sự hiểu biết sâu sắc về nội dung, chủ đề, tư tưởng, và cảm xúc của bài thơ.\r\n- Có góc nhìn, kiến giải riêng, không chỉ lặp lại ý tưởng cũ.', 0, 2),
(2, 'Phân Tích Hình Thức & Nghệ Thuật', 1, '- Phân tích hiệu quả của việc sử dụng ngôn từ, hình ảnh.\r\n- Phân tích tác dụng của các biện pháp tu từ (không chỉ gọi tên).\r\n- Phân tích vai trò của các yếu tố nhạc tính (vần, nhịp, thanh điệu).\r\n- Quan trọng: Liên kết chặt chẽ các yếu tố hình thức với nội dung, luận điểm.', 0, 3),
(3, 'Lập Luận và Dẫn Chứng', 1, '- Sử dụng dẫn chứng (trích thơ) chính xác, phù hợp, vừa đủ.\r\n- Phân tích sâu dẫn chứng, không chỉ diễn xuôi hay kể lại.\r\n- Lập luận logic, các luận điểm nhỏ bổ trợ cho luận điểm chính.\r\n- Lý lẽ thuyết phục, tránh suy diễn chủ quan, vô căn cứ.', 0, 3),
(4, 'Cấu trúc và diễn đạt', 1, '- Bố cục 3 phần rõ ràng, cân đối.\r\n- Chuyển ý, chuyển đoạn mượt mà, hợp lý.\r\n- Văn phong mạch lạc, trong sáng, giàu cảm xúc (khi cần) và phù hợp với văn nghị luận.\r\n- Sử dụng thuật ngữ chính xác.', 0, 2),
(5, 'Cấu trúc, diễn đạt', 2, '- Bố cục 3 phần rõ ràng, cân đối.\r\n- Chuyển ý, chuyển đoạn mượt mà, hợp lý.\r\n- Văn phong mạch lạc, trong sáng, giàu cảm xúc (khi cần) và phù hợp với văn nghị luận.\r\n- Sử dụng thuật ngữ chính xác.', 2, 10),
(6, 'Lập luận, dẫn chứng', 2, '- Sử dụng dẫn chứng (trích thơ) chính xác, phù hợp, vừa đủ.\r\n- Phân tích sâu dẫn chứng, không chỉ diễn xuôi hay kể lại.\r\n- Lập luận logic, các luận điểm nhỏ bổ trợ cho luận điểm chính.\r\n- Lý lẽ thuyết phục, tránh suy diễn chủ quan, vô căn cứ.', 3, 10),
(7, 'Luận Điểm và Mức Độ Hiểu', 2, '- Luận điểm chính (thesis) rõ ràng, sắc sảo, có tính khám phá.\r\n- Thể hiện sự hiểu biết sâu sắc về nội dung, chủ đề, tư tưởng, và cảm xúc của bài thơ.\r\n- Có góc nhìn, kiến giải riêng, không chỉ lặp lại ý tưởng cũ.', 2, 10),
(8, 'Phân Tích Hình Thức & Nghệ Thuật', 2, '- Phân tích hiệu quả của việc sử dụng ngôn từ, hình ảnh.\r\n- Phân tích tác dụng của các biện pháp tu từ (không chỉ gọi tên).\r\n- Phân tích vai trò của các yếu tố nhạc tính (vần, nhịp, thanh điệu).\r\n- Quan trọng: Liên kết chặt chẽ các yếu tố hình thức với nội dung, luận điểm.', 2, 10),
(9, 'Cốt truyện', 3, '', 0, 10),
